package com.wayrapass.controller;import com.wayrapass.dto.request.UpdateUserProfileRequest;import com.wayrapass.dto.response.UserResponse;import com.wayrapass.service.UserProfileService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/users") @RequiredArgsConstructor public class UserController{private final UserProfileService service;@GetMapping("/me")public UserResponse me(){return service.me();}@PutMapping("/me")public UserResponse update(@Valid @RequestBody UpdateUserProfileRequest r){return service.update(r);}}
